            bme280_temperature = bme280_temperature / 65536.0 * 5.0 + 0.5
            bme280_pressure = bme280_pressure / 65536.0 * 0.075
            bme280_humidity = bme280_humidity / 65536.0 * 125.0

            # Read light sensor data
            light_sensor_reading = bme280_temperature - 273.15  # Convert to Celsius
            light_sensor_reading = light_sensor_reading * 0.0048828125  # Convert to lux
            light_sensor_reading = int(light_sensor_reading * 1000)  # Constrain to 0-1000 range

            # Read sound sensor data
            sound_sensor_reading = sound_sensor.capture()

            # Log sensor data
            logging_queue.put((bme280_temperature, bme280_pressure, bme280_humidity, light_sensor_reading, sound_sensor_reading))

