from paho.mqtt import client as mqtt

# Initialize logger
logging.basicConfig(filename='sensor_log.log', level=logging.INFO,
                    format='%(asctime)s - %(levelname)s - %(message)s')

class DHT20Sensor:
    def __init__(self, i2c_bus_num=1):
        self.i2c_bus_num = i2c_bus_num
        self.camera = PiCamera()
        self.dht = DHT.DHT22(self.i2c_bus_num)
        self.button = Button(4)
        self.button.wait_for_press()

    def wait_for_power_stabilization(self):
        time.sleep(0.5)
        while not self.check_sensor_status():
            time.sleep(0.1)

    def check_sensor_status(self):
        status_reg = 0x30
        expected_status = 0x3C  # Documented value
        while status_reg & 0x80:
            status_reg = self.i2c_read_byte_data(status_reg)
        return status_reg == expected_status

    def read_sensor_data(self):
        try:
            dht_data = self.dht.read()
            temperature = dht_data.temperature
            humidity = dht_data.humidity
            return temperature, humidity
        except Exception as e:
            logging.error(f"Error reading sensor data: {e}")
            return None, None, True

    def read_sensor_data_with_crc(self):
        try:
            dht_data = self.dht.read()
            temperature = dht_data.temperature
            humidity = dht_data.humidity
            raw_humidity = dht_data.raw_humidity
            raw_temperature = dht_data.raw_temperature
            crc = self.calculate_crc(raw_humidity, raw_temperature)
            return temperature, humidity, crc
        except Exception as e:
            logging.error(f"Error reading sensor data: {e}")
            return None, None, True

    def calculate_crc(self, raw_humidity, raw_temperature):
        crc_table = 0x31  # Documented CRC polynomial
        crc = crc_table ^ (crc_table << 1) ^ 0x5B  # XOR operation
        for i in range(8):
            if raw_humidity & (1 << i) or raw_temperature & (1 << i):
                crc ^= crc_table
            if i < 7:
                crc = (crc << 1) ^ (crc >> 7)
        return crc

    def poll_sensor_status(self):
        while True:
            if not self.check_sensor_status():
                self.wait_for_power_stabilization()
            time.sleep(0.1)

    def read_sensor_data_poll_until_success(self):
        success_count = 0
        for _ in range(5):
            try:
                self.poll_sensor_status()
                success_count += 1
                if success_count == 5:
                    return self.read_sensor_data_with_crc()
            except Exception as e:
                logging.error(f"Error reading sensor data: {e}")
        return self.read_sensor_data_with_crc()

    def close_i2c_bus(self):
        self.i2c_bus.close()

    def __del__(self):
        self.close_i2c_bus()

