    try:
        dht.measure(dht.DHT11)
        temperature = round(dht.temperature, 1)
        humidity = round(dht.humidity, 1)
        return temperature, humidity
    except RuntimeError:
        print("Failed to read DHT22. Retrying...")
        return None, None

def publish_mqtt(temperature, humidity):
