```python
import time
import json
import picamera
import RPi.GPIO as GPIO
from adafruit_circuitpython_mqtt import MQTT, MQTTClient
from paho.mqtt import client as mqtt_client

# Set up GPIO and MQTT
GPIO.setmode(GPIO.BCM)
GPIO.setup(17, GPIO.IN, pull_up_down=GPIO.PUD_UP)
mqtt = MQTT(client=mqtt_client.Client())

# Define the JSON structure
def generate_report():
    report = {
        "part_id": "PART-204",
        "passed": True,
        "defect_count": 0
    }
    return json.dumps(report)

# Function to handle MQTT connection and transmission
def on_connect(client, userdata, flags, rc):
    print(f"Connected to MQTT broker with result code {rc}")
    client.subscribe("quality")

def on_message(client, userdata, msg):
    payload = json.loads(msg.payload.decode())
    if msg.topic == "quality":
        if msg.payload == "1":
            report = generate_report()
            mqtt.publish("quality", report)
            print("Report sent successfully")
        elif msg.payload == "0":
            report = generate_report()
            mqtt.publish("quality", report)
            print("Report sent successfully")
        else:
            print("Invalid payload received")

# Main loop
def main():
    while True:
        try:
            # Check button state
            if GPIO.input(17):
                report = generate_report()
                mqtt.publish("quality", report)
                print("Report sent successfully")
            else:
                print("No button press detected")
        except KeyboardInterrupt:
            print("KeyboardInterrupt detected, exiting...")
            GPIO.cleanup()

if __name__ == "__main__":
    try:
        main()
    except Exception as e:
        print(f"An error occurred: {e}")
        # Release GPIO resources
        GPIO.cleanup()
    except KeyboardInterrupt:
        print("KeyboardInterrupt detected, exiting...")
        # Release GPIO resources
        GPIO.cleanup()
