        try:
            state = self.state_pin.value
            if state == 1:
                self.state = True
            else:
                self.state = False
            self.log_file.write(f"Door state: {self.state}\n")
        except AttributeError:
            self.log_file.write("Error: Reed switch not found or not accessible\n")
        except Exception as e:
            self.log_file.write(f"Error: {e}\n")

    def open_door(self):
        try:
            self.relay_one.on()
            time.sleep(0.5)
            self.relay_one.off()
            self.state = True
            self.log_file.write(f"Door opened at {time.ctime()}\n")
        except Exception as e:
            self.log_file.write(f"Error: {e}\n")

    def close_door(self):
        try:
            self.relay_one.on()
            time.sleep(0.5)
            self.relay_one.off()
            self.state = False
            self.log_file.write(f"Door closed at {time.ctime()}\n")
        except Exception as e:
            self.log_file.write(f"Error: {e}\n")

    def close_door_if_open(self):
        if self.state:
            self.close_door()
        else:
            self.open_door()

