class ESP8266Control:
    def __init__(self, port='/dev/serial0', baud_rate=115200, timeout=1.0):
        self.port = port
        self.baud_rate = baud_rate
        self.timeout = timeout
        self.pi = adafruit_pigpio.Pigpio()
        self.pi.setup(board.Pin(15), board.Pin(14), pull_up_down=board.Pin.PUD_UP)
        self.uart = busio.UART(board.UART1, baud_rate=self.baud_rate, timeout=self.timeout)
        self.uart.init_output()

    def _send_command(self, command):
        try:
            response = self.uart.write(command.encode())
            response = response.decode()
            if response.startswith(b'OK'):
                return response[len(b'OK'):]
            elif response.startswith(b'ERROR'):
                return None
            elif response.startswith(b'FAIL'):
                return None
        except Exception as e:
            print(f"Error sending command: {e}")
            return None

    def test_connection(self):
        command = b'AT'
        response = self._send_command(command)
        if response:
            return response.startswith(b'OK')

    def restart(self):
        command = b'AT+RST'
        self._send_command(command)
        time.sleep(2)
        response = self._send_command(command)
        if response:
            return response.startswith(b'ready')

    def connect_wifi(self, ssid, password):
        command = b'AT+CWJAP=\'' + ssid + '\',\'' + password + '\''
        self._send_command(command)
        time.sleep(2)
        return self.test_connection()

    def disconnect_wifi(self):
        command = b'AT+CWQAP'
        self._send_command(command)

    def get_ip(self):
        command = b'AT+CIFSR'
        response = self._send_command(command)
        if response:
            return response.decode().split(b':')[1].strip()

    def send_http_request(self, method, url, host='http://127.0.0.1', port=80, headers=None, data=None):
        try:
            self.pi.set_mode(board.Pin(14), board.Pin.OUT)
            self.pi.set_mode(board.Pin(15), board.Pin.OUT)
            self.uart.init_output()
            self.uart.write(b'AT+CIPSTART=1,\'' + method + '\',\'' + url + '\',\'' + host + '\',\'' + str(port) + '\'')
            if headers:
                self.uart.write(b'AT+CIPSEND=1')
                for header in headers:
                    self.uart.write(header.encode())
                self.uart.write(b'\r')
            if data:
                self.uart.write(b'AT+CIPSEND=' + str(len(data)) + b'\r')
                self.uart.write(data.encode())
                self.uart.write(b'\r')
            response = self._send_command(b'+IPD:')
            if response:
                response = response.decode().split(b':')[1].strip()
                return response
        except Exception as e:
            print(f"Error sending HTTP request: {e}")
            return None

    def receive_http_response(self, timeout=5.0):
        try:
            response = self.uart.read(timeout=timeout)
            if response:
                response = response.decode()
                if response.startswith(b'+IPD:'):
                    payload = response[len(b'+IPD:'):]
                    return payload.split(b':')[1].strip()
                else:
                    return None
        except Exception as e:
            print(f"Error receiving HTTP response: {e}")
            return None

    def close_uart(self):
        self.uart.close()
        self.pi.deinit()

if __name__ == "__main__":
    esp8266_control = ESP8266Control()
    if esp8266_control.test_connection():
        print("Connection successful")
        esp8266_control.connect_wifi('your_ssid', 'your_password')
        if esp8266_control.test_connection():
            print("WiFi connected")
            esp8266_control.disconnect_wifi()
            print("Disconnected from WiFi")
            ip_address = esp8266_control.get_ip()
            print(f"IP address: {ip_address}")
            esp8266_control.send_http_request('GET', 'http://127.0.0.1', headers={'Host': 'example.com'}, data=None)
            response = esp8266_control.receive_http_response()
            if response:
                print(f"Response: {response}")
            esp8266_control.close_uart()
        else:
            print("Failed to connect to WiFi")
    else:
        print("Failed to test connection")

