import os
import time
import threading
import gpiozero
import picamera2
import adafruit_circuitpython_mqtt
import paho.mqtt.client as mqtt
from json import dumps

# Set up GPIO pins
uart_pin = 18
led_pin = 23

# Set up serial communication
ser = picamera2.PiSerial('/dev/ttyUSB0', baudrate=9600, timeout=0.1)

# Set up MQTT client
mqtt_client = adafruit_circuitpython_mqtt.MqttClient()

# Set up MQTT topic
mqtt_topic = "scpi_instrument"

# Set up MQTT parameters
mqtt_params = {
    "client_id": "raspberrypi",
    "username": "user",
    "password": "password",
    "broker": "mqtt.example.com",
    "port": 1883,
}

# Set up MQTT callback
def on_connect(client, userdata, flags, rc):
    print(f"Connected with result code {rc}")
    client.subscribe(mqtt_topic)

def on_message(client, userdata, msg):
    print(f"Received message: {msg.payload.decode('utf-8')}")

# Set up HTTP server
app = gpiozero.Application()

@app.event
def on_start():
    led_on()

@app.event
def on_stop():
    led_off()

@app.event
def on_reconnect(client):
    print("Reconnected to MQTT broker")

@app.event
def on_message(client, userdata, message):
    if message.topic == mqtt_topic:
        if message.payload.decode('utf-8') == "*IDN?":
            led_on()
            time.sleep(0.1)
            response = ser.readline().decode('utf-8')
            led_off()
            print(response)
        elif message.payload.decode('utf-8') == "":
            led_on()
            time.sleep(0.1)
            response = ser.readline().decode('utf-8')
            led_off()
            print(response)
        else:
            print("Error: Invalid response from SCPI instrument")

@app.event
def on_mqtt_message(client, userdata, message):
    if message.topic == mqtt_topic:
        if message.payload.decode('utf-8') == "":
            led_on()
            time.sleep(0.1)
            response = ser.readline().decode('utf-8')
            led_off()
            print(response)
        else:
            print("Error: Invalid response from SCPI instrument")

# Main loop
while True:
    try:
        app.run(debug=True, host='0.0.0.0', port=8080)
    except KeyboardInterrupt:
        print("Exiting the application")
        app.stop()
    except Exception as e:
        print(f"An error occurred: {e}")
        app.stop()

# Release hardware resources
ser.close()
